import { DataTable, Indicator, Tag, type DataTableColumn } from "@jiran/ds-react";

type Row = { id: string; time: string; sev: "critical" | "high" | "medium" | "low"; event: string; target: string; count: number; status: "blocked" | "review" | "ok" };
const ROWS: Row[] = [
  { id: "1", time: "09:41:12", sev: "critical", event: "랜섬웨어 행위 탐지", target: "PC-2041 · 김민준", count: 3, status: "blocked" },
  { id: "2", time: "09:40:58", sev: "medium", event: "미승인 USB 연결", target: "PC-1187 · 이서연", count: 1, status: "review" },
  { id: "3", time: "09:38:03", sev: "low", event: "정책 동기화 완료", target: "Server-03", count: 12, status: "ok" },
  { id: "4", time: "09:36:47", sev: "high", event: "알려진 악성코드 차단", target: "PC-0932 · 박지훈", count: 2, status: "blocked" },
];
const SEV_LABEL = { critical: "Critical", high: "High", medium: "Medium", low: "Low" };
const SEV_RANK = { critical: 4, high: 3, medium: 2, low: 1 };
const STATUS = { blocked: ["차단", "danger"], review: ["검토 필요", "warn"], ok: ["정상", "ok"] } as const;

const COLUMNS: DataTableColumn<Row>[] = [
  { key: "time", header: "시간", sortable: true },
  { key: "sev", header: "심각도", sortable: true, sortValue: (r) => SEV_RANK[r.sev], render: (r) => <Tag tone={r.sev}>{SEV_LABEL[r.sev]}</Tag> },
  { key: "event", header: "이벤트", render: (r) => <a href="#" className="link">{r.event}</a> },
  { key: "target", header: "대상", sortable: true },
  { key: "count", header: "횟수", num: true, sortable: true },
  { key: "status", header: "상태", render: (r) => <Indicator tone={STATUS[r.status][1]}>{STATUS[r.status][0]}</Indicator> },
];

export default function Example() {
  return <DataTable columns={COLUMNS} rows={ROWS} rowKey={(r) => r.id} defaultSort={{ key: "time", dir: "desc" }} />;
}

import { useState } from "react";
import { ActionBar, Button, DataTable, Icon, Switch, type DataTableColumn } from "@jiran/ds-react";

type Policy = { id: string; name: string; group: string; targets: number; updated: string; enabled: boolean };
const ROWS: Policy[] = [
  { id: "p1", name: "외부 USB 차단", group: "전체", targets: 1284, updated: "2026-09-06", enabled: true },
  { id: "p2", name: "스크립트 실행 제한", group: "개발팀 제외", targets: 1102, updated: "2026-09-02", enabled: true },
  { id: "p3", name: "원격 접속 허용 목록", group: "인프라팀", targets: 48, updated: "2026-08-21", enabled: false },
];
const COLUMNS: DataTableColumn<Policy>[] = [
  { key: "name", header: "정책" },
  { key: "group", header: "적용 그룹" },
  { key: "targets", header: "대상", num: true, render: (r) => r.targets.toLocaleString() },
  { key: "updated", header: "수정" },
  { key: "enabled", header: "사용", render: (r) => <Switch size="sm" defaultChecked={r.enabled} aria-label="사용" /> },
];

export default function Example() {
  const [selected, setSelected] = useState(new Set(["p1", "p2"]));
  return (
    <DataTable
      columns={COLUMNS}
      rows={ROWS}
      rowKey={(r) => r.id}
      selectable
      selected={selected}
      onSelectedChange={setSelected}
      actionBar={(sel) => (
        <ActionBar count={sel.size}>
          <Button size="sm" variant="secondary">허용 처리</Button>
          <Button size="sm" variant="secondary" leading={<Icon name="download" />}>내보내기</Button>
          <Button size="sm" variant="danger-secondary">삭제</Button>
        </ActionBar>
      )}
    />
  );
}

import { DataTable, Tag, type DataTableColumn } from "@jiran/ds-react";

type Log = { id: number; time: string; level: "critical" | "medium" | "info"; src: string; msg: string };
const LEVEL = { critical: "CRIT", medium: "WARN", info: "INFO" };
const ROWS: Log[] = [
  { id: 1, time: "2026-09-07 09:41:12.031", level: "critical", src: "10.0.4.21", msg: "process.create blocked: rundll32.exe → cryptor.dll" },
  { id: 2, time: "2026-09-07 09:41:11.870", level: "medium", src: "10.0.4.21", msg: "usb.attach vendor=0x0781 product=0x5583" },
  { id: 3, time: "2026-09-07 09:41:09.114", level: "info", src: "10.0.0.3", msg: "policy.sync ok (rev 2041)" },
  { id: 4, time: "2026-09-07 09:41:08.552", level: "info", src: "10.0.0.3", msg: "agent.checkin 1284/1284" },
];
const COLUMNS: DataTableColumn<Log>[] = [
  { key: "time", header: "시간" },
  { key: "level", header: "레벨", render: (r) => <Tag tone={r.level} size="sm">{LEVEL[r.level]}</Tag> },
  { key: "src", header: "소스" },
  { key: "msg", header: "메시지" },
];

export default function Example() {
  return <DataTable compact columns={COLUMNS} rows={ROWS} rowKey={(r) => String(r.id)} rowProps={() => ({ log: true })} />;
}

import { DataTable } from "@jiran/ds-react";

type Row = { id: string; time: string; sev: string; event: string; target: string };

export default function Example() {
  return (
    <DataTable<Row>
      columns={[{ key: "time", header: "시간" }, { key: "sev", header: "심각도" }, { key: "event", header: "이벤트" }, { key: "target", header: "대상" }]}
