.list.hover li:hover{background:var(--bg-subtle);cursor:pointer}
.list li.on{background:var(--accent-subtle)}
.list .primary{font-weight:500;display:block}
.list .meta{display:block;font-size:12px;color:var(--text-tertiary)}
.list .end{margin-left:auto;display:flex;gap:8px;align-items:center;flex:none}
.list.plain{border:0;background:transparent;border-radius:0}
.list.plain li{padding:10px 0}
.list.dense li{padding:8px 16px;font-size:14px}
.tile .tag{position:absolute;top:12px;right:12px}
.status-item .indicator{font-weight:600}
@keyframes pulse{70%{box-shadow:0 0 0 8px transparent}}

