/* JS Design System v0.6 · .kpi, .kpi-grid, .chart, .chart-card, .donut, .donut-row, .chart-legend, .sparkline · 토큰(var(--*))은 assets/style.css :root 참고 */
.kpi{background:var(--bg-surface);border-radius:var(--radius-lg);box-shadow:var(--shadow-1);padding:20px 24px;min-width:180px;display:flex;flex-direction:column;gap:4px}
.kpi .label{font-size:12px;color:var(--text-tertiary);font-weight:500}
.kpi .value{font-size:32px;font-weight:700;letter-spacing:-.02em;line-height:1.2;font-variant-numeric:tabular-nums;white-space:nowrap}
.kpi .value small{font-size:16px;font-weight:500;color:var(--text-tertiary);margin-left:2px}
.kpi .delta{font-size:12px;font-weight:600;color:var(--text-secondary)}
.kpi .delta svg{width:12px;height:12px;vertical-align:-1px}
.kpi .delta.up{color:var(--danger)}
.kpi .delta.down{color:var(--success)}
.kpi.critical .value{color:var(--sev-critical)}
.kpi.high .value{color:var(--sev-high)}
.kpi-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px;width:100%}
.chart{display:flex;flex-direction:column;gap:10px;width:100%;font-size:12px}
.chart .row{display:grid;grid-template-columns:120px 1fr 56px;align-items:center;gap:12px}
.chart .row .lbl{color:var(--text-secondary);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.chart .bar{height:12px;border-radius:999px;background:var(--bg-panel);overflow:hidden}
.chart .bar i{display:block;height:100%;background:var(--accent);border-radius:999px}
.chart .bar.critical i{background:var(--sev-critical)}
.chart .bar.high i{background:var(--sev-high)}
.chart .bar.medium i{background:var(--sev-medium)}
.chart .bar.low i{background:var(--sev-low)}
.chart .num{text-align:right;font-variant-numeric:tabular-nums;color:var(--text-secondary)}
.chart-card{background:var(--bg-surface);border-radius:var(--radius-lg);box-shadow:var(--shadow-1);padding:20px 24px;display:flex;flex-direction:column;gap:16px;width:100%}
.chart-card .chart-title{font-size:16px;font-weight:600;margin:0;display:flex;justify-content:space-between;align-items:center}
.donut{width:120px;height:120px;border-radius:50%;display:grid;place-items:center;flex:none;background:conic-gradient(var(--sev-critical) 0 18%,var(--sev-high) 18% 45%,var(--sev-medium) 45% 75%,var(--sev-low) 75% 100%)}
.donut::after{content:attr(data-label);width:80px;height:80px;border-radius:50%;background:var(--bg-surface);display:grid;place-items:center;font-weight:700;font-size:16px;font-variant-numeric:tabular-nums}
.donut-row{display:flex;align-items:center;gap:24px}
.chart-legend{display:flex;flex-wrap:wrap;gap:8px 20px;font-size:12px;color:var(--text-secondary)}
.chart-legend span{display:inline-flex;align-items:center;gap:6px}
.chart-legend i{width:10px;height:10px;border-radius:2px;background:var(--gray-400);flex:none}
.chart-legend b{color:var(--text-primary);font-variant-numeric:tabular-nums}
