.field input:focus,.field textarea:focus{border-color:var(--border-focus);outline:2px solid color-mix(in srgb,var(--border-focus) 30%,transparent)}
.field input:disabled,.field textarea:disabled{background:var(--bg-panel);color:var(--text-disabled);cursor:not-allowed}
